/* ===== FONTS: Roboto Slab (headings) + Inter (UI) — self-hosted, canonical ===== */
@font-face {
  font-family: "Roboto Slab";
  font-style: normal;
  font-weight: 400 900;
  font-display: optional;
  src: url("./assets/fonts/RobotoSlab-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}

/* ===== FINAL FIX: KGX-B4 + HERO BENEFITS (2026-05-15) ===== */
@media (hover: hover) and (pointer: fine) {
  /* 1) Block "Почему самостоятельно..." cards: remove moving glare completely */
  body #kgx-b4 .kgx-b4__item,
  body #kgx-b4 .kgx-b4__item:hover {
    animation: none !important;
    filter: none !important;
    transform: translate3d(0, 0, 0) !important;
  }

  body #kgx-b4 .kgx-b4__item::before,
  body #kgx-b4 .kgx-b4__item::after {
    animation: none !important;
    transform: none !important;
    will-change: auto !important;
  }

  body #kgx-b4 .kgx-b4__item::after {
    content: none !important;
  }

  body #kgx-b4 .kgx-b4__item::before {
    content: "" !important;
    position: absolute !important;
    inset: 0 !important;
    pointer-events: none !important;
    opacity: 0 !important;
    background:
      radial-gradient(circle at 84% 16%, rgba(255, 226, 185, .14) 0%, rgba(236, 132, 58, .08) 24%, rgba(236, 132, 58, .03) 40%, transparent 64%),
      linear-gradient(135deg, rgba(255, 255, 255, .05) 0%, transparent 42%) !important;
    transition: opacity 180ms ease !important;
    z-index: 1 !important;
  }

  body #kgx-b4 .kgx-b4__item:hover::before {
    opacity: 1 !important;
  }

  body #kgx-b4 .kgx-b4__item > * {
    position: relative !important;
    z-index: 2 !important;
  }

  /* 2) Same block CTA/form underlay: remove running glare */
  body #kgx-b4 .kgx-b4__cta,
  body #kgx-b4 .kgx-b4__cta:hover,
  body #kgx-b4 .kg-cta__inner,
  body #kgx-b4 .kg-cta__inner:hover {
    animation: none !important;
    filter: none !important;
    transform: none !important;
  }

  body #kgx-b4 .kgx-b4__cta::before,
  body #kgx-b4 .kgx-b4__cta::after,
  body #kgx-b4 .kg-cta__inner::after {
    content: none !important;
    animation: none !important;
    transform: none !important;
  }

  body #kgx-b4 .kg-cta__inner::before {
    transform: none !important;
    animation: none !important;
  }

  /* 3) First offer block (4 cards): proper premium static hover */
  body .hero-benefits-grid.hero-benefits-grid--intro .hero-benefit-card.hero-benefit-card--intro,
  body .hero-benefits-grid.hero-benefits-grid--intro .hero-benefit-card.hero-benefit-card--intro:hover {
    animation: none !important;
    filter: none !important;
    will-change: transform, box-shadow, border-color !important;
    transition:
      transform 210ms cubic-bezier(.2, .7, .2, 1),
      border-color 210ms ease,
      box-shadow 210ms ease !important;
  }

  body .hero-benefits-grid.hero-benefits-grid--intro .hero-benefit-card.hero-benefit-card--intro::before,
  body .hero-benefits-grid.hero-benefits-grid--intro .hero-benefit-card.hero-benefit-card--intro::after {
    animation: none !important;
    transform: none !important;
  }

  body .hero-benefits-grid.hero-benefits-grid--intro .hero-benefit-card.hero-benefit-card--intro::after {
    content: "" !important;
    position: absolute !important;
    inset: 0 !important;
    pointer-events: none !important;
    opacity: 0 !important;
    background:
      radial-gradient(circle at 86% 16%, rgba(255, 226, 185, .16) 0%, rgba(236, 132, 58, .10) 24%, rgba(236, 132, 58, .04) 42%, transparent 66%),
      linear-gradient(135deg, rgba(255, 255, 255, .05) 0%, transparent 44%) !important;
    transition: opacity 190ms ease !important;
    z-index: 1 !important;
  }

  body .hero-benefits-grid.hero-benefits-grid--intro .hero-benefit-card.hero-benefit-card--intro:hover {
    transform: translate3d(0, -3px, 0) !important;
    border-color: rgba(236, 132, 58, .34) !important;
    box-shadow:
      0 18px 42px rgba(0, 0, 0, .4),
      inset 0 1px 0 rgba(255, 255, 255, .11),
      inset 0 0 0 1px rgba(236, 132, 58, .08) !important;
  }

  body .hero-benefits-grid.hero-benefits-grid--intro .hero-benefit-card.hero-benefit-card--intro:hover::after {
    opacity: 1 !important;
  }

  body .hero-benefits-grid.hero-benefits-grid--intro .hero-benefit-card.hero-benefit-card--intro > * {
    position: relative !important;
    z-index: 2 !important;
  }
}
