}

html,
body {
  font-family: var(--font-ui);
  overflow-x: clip;
}

h1, h2, h3, h4, h5, h6,
.hero-title,
.section-title,
.kg-title,
.hero-investment__title {
  font-family: var(--font-heading);
}

.keis-header,
.keis-header *:not(img):not(svg) {
  font-family: var(--font-ui);
}

input,
textarea,
select,
button,
::placeholder,
.form-input,
.keis-input,
.hero-form *,
.modal-form *,
.success-modal * {
