/* KF FLAGS: pencil ordinal marks on the torn-paper cards. */
.kf-flags__rows,
.kf-flags__grid {
  counter-reset: kf-pencil-card;
}

.kf-flags :where(.kf-flag-card, .kf-flag) {
  counter-increment: kf-pencil-card;
  --kf-pencil-ink: rgba(25, 25, 25, 0.55);
  --kf-pencil-gap: clamp(18px, 1.45vw, 26px);
  --kf-pencil-top: clamp(13px, 1.2vw, 20px);
  --kf-pencil-size: clamp(1.7rem, 2vw, 2.35rem);
}

.kf-flags .kf-flag-card__num,
.kf-flags .kf-flag-num,
.kf-flags .kf-flag-card .kf-flag-card__num,
.kf-flags .kf-flag .kf-flag-card__num {
  display: block !important;
  position: absolute !important;
  left: auto;
  right: calc(100% + var(--kf-pencil-gap));
  top: 0.02em;
  z-index: 3;
  width: calc(var(--kf-pencil-size) * 1.2);
  height: calc(var(--kf-pencil-size) * 1.05);
  margin: 0;
  overflow: visible;
  color: transparent;
  font-size: 0;
  line-height: 1;
  pointer-events: none;
}

.kf-flags .kf-flag-card__num::after,
.kf-flags .kf-flag-num::after {
  content: counter(kf-pencil-card) ".";
  display: block;
  color: var(--kf-pencil-ink);
  font-family: "Bradley Hand", "Segoe Print", "Comic Sans MS", cursive;
  font-size: var(--kf-pencil-size);
  font-weight: 700;
  line-height: 0.95;
  letter-spacing: 0;
  transform: rotate(-8deg);
  transform-origin: 42% 58%;
  text-shadow: 0 0.8px 0 rgba(255, 255, 255, 0.44), 0 1px 2px rgba(25, 25, 25, 0.18);
  opacity: 0.92;
}

.kf-flags .kf-flag-card__num::before,
.kf-flags .kf-flag-num::before {
  content: "";
  position: absolute;
  left: calc(var(--kf-pencil-size) * -0.4);
  top: calc(var(--kf-pencil-size) * -0.44);
  width: calc(var(--kf-pencil-size) * 1.95);
  height: calc(var(--kf-pencil-size) * 1.9);
  background-image: var(--kf-pencil-ring);
  background-repeat: no-repeat;
  background-position: center;
  background-size: 100% 100%;
  opacity: 0;
  transform: rotate(-11deg) scale(0.72);
  transform-origin: 52% 54%;
  clip-path: polygon(0 0, 22% 0, 22% 100%, 0 100%);
  filter: drop-shadow(0 1px 0 rgba(255, 255, 255, 0.34));
  transition: clip-path 180ms cubic-bezier(0.2, 0.9, 0.2, 1), opacity 70ms ease, transform 180ms cubic-bezier(0.2, 0.9, 0.2, 1);
}

