  --cases-text: #ffffff;
  --cases-muted: rgba(255, 255, 255, 0.72);
  --cases-success: #79d36b;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding: clamp(82px, 8vw, 128px) 0;
  scroll-margin-top: 96px;
  background:
    radial-gradient(circle at 70% 12%, rgba(242, 138, 46, 0.16), transparent 32%),
