    linear-gradient(90deg, rgba(0, 0, 0, 0.46), transparent 28%, rgba(0, 0, 0, 0.44)),
    radial-gradient(ellipse at 50% 0%, rgba(255, 154, 61, 0.12), transparent 54%);
