  .credit-premium-section__hero-card .k-header__box:hover,
  .credit-premium-card:hover,
  .pressure-premium-section__hero-card .k-header__box:hover,
  .pressure-premium-card:hover,
  .pressure-premium-note:hover {
    animation: kg-glass-shimmer 760ms cubic-bezier(.22, .61, .36, 1) 1;
    filter: brightness(1.045) saturate(1.03);
  }

  /* Directional shimmer stripe only on safe cards (free ::after) */
  .investment-process .work-step-body,
  .case-showcase__facts,
  .modal-form,
  .success-modal,
  #kgx-b4 .kgx-b4__item,
  #kgx-b4 .kgx-b4__cta {
    position: relative;
    overflow: hidden;
    isolation: isolate;
  }

  .investment-process .work-step-body::after,
  .case-showcase__facts::after::after,
  .modal-form::after,
  .success-modal::after,
  #kgx-b4 .kgx-b4__item::after,
  #kgx-b4 .kgx-b4__cta::after {
    content: "";
    position: absolute;
    inset: -38% -56%;
    z-index: 3;
    pointer-events: none;
    opacity: 0;
    background: linear-gradient(
      115deg,
      transparent 0%,
      transparent 40%,
      rgba(255, 255, 255, .03) 44%,
      rgba(255, 214, 170, .14) 49%,
      rgba(255, 255, 255, .16) 52%,
      rgba(255, 168, 86, .08) 57%,
      transparent 64%,
      transparent 100%
    );
    mix-blend-mode: screen;
    transform: translate3d(-68%, 0, 0) rotate(0.001deg);
    transition:
      transform 900ms cubic-bezier(.18, .76, .22, 1),
      opacity 260ms ease;
  }

  .investment-process .work-step-body:hover::after,
  .case-showcase__facts:hover::after:hover::after,
  .modal-form:hover::after,
  .success-modal:hover::after,
  #kgx-b4 .kgx-b4__item:hover::after,
