    opacity: 1;
    transform: translate3d(68%, 0, 0) rotate(0.001deg);
  }
}

@keyframes kg-glass-shimmer {
  0% {
    transform: translateY(0);
    box-shadow: none;
    filter: brightness(1) saturate(1);
  }
  35% {
    transform: translateY(-1px);
    box-shadow:
      0 10px 24px rgba(0, 0, 0, .18),
      0 0 0 1px rgba(255, 255, 255, .03) inset;
    filter: brightness(1.058) saturate(1.035);
