    box-shadow:
      0 7px 18px rgba(0, 0, 0, .13),
      0 0 0 1px rgba(255, 243, 223, .035) inset;
    filter: brightness(1.038) saturate(1.02);
  }
  100% {
    transform: translateY(0);
    box-shadow: none;
    filter: brightness(1) saturate(1);
  }
}

