    linear-gradient(90deg, rgba(242,154,52,var(--footer-pin-debug)), rgba(242,154,52,var(--footer-pin-debug))),
    linear-gradient(rgba(245,245,245,var(--footer-pin-debug)), rgba(245,245,245,var(--footer-pin-debug))),
    linear-gradient(90deg, rgba(245,245,245,var(--footer-pin-debug)), rgba(245,245,245,var(--footer-pin-debug)));
