html:has(body[data-page="auto-law-unavailable"]) {
  min-height: 100%;
  background: #070504;
}

body[data-page="auto-law-unavailable"] {
  min-height: 100vh;
  min-height: 100dvh;
  margin: 0;
  color: #f7efe7;
  background-color: #070504;
  background-image:
    linear-gradient(90deg, rgba(7, 5, 4, 0.86) 0%, rgba(7, 5, 4, 0.54) 34%, rgba(7, 5, 4, 0.08) 66%, rgba(7, 5, 4, 0.1) 100%),
    url("/block/404/keis-404-section-unavailable.webp");
  background-repeat: no-repeat;
  background-size: cover, auto 100%;
  background-position: center, right center;
}

.auto-unavailable {
  position: relative;
  display: flex;
  align-items: center;
  width: min(1180px, calc(100% - 56px));
  min-height: 100vh;
  min-height: 100dvh;
  margin: 0 auto;
  padding: clamp(40px, 6vw, 72px) 0;
}

.auto-unavailable__content {
  width: min(460px, 100%);
  margin-right: auto;
}

.auto-unavailable__content > p {
  margin: 0;
  color: rgba(255, 247, 238, 0.9);
  font: 600 clamp(18px, 1.5vw, 24px)/1.45 Inter, Arial, sans-serif;
  text-shadow: 0 4px 18px rgba(0, 0, 0, 0.58);
}

.auto-unavailable__button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  margin-top: 24px;
  padding: 0 30px;
  border: 1px solid rgba(255, 164, 54, 0.62);
  border-radius: 8px;
  color: #130b07;
  background: linear-gradient(180deg, #ffb36a 0%, #ff8a1f 100%);
  font: 800 15px/1 Inter, Arial, sans-serif;
  text-decoration: none;
  box-shadow: 0 18px 42px rgba(255, 128, 26, 0.24);
  transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
}

.auto-unavailable__button:hover,
.auto-unavailable__button:focus-visible {
  filter: brightness(1.05);
  box-shadow: 0 20px 48px rgba(255, 128, 26, 0.32);
  transform: translateY(-1px);
}

@media (max-width: 1100px) {
  body[data-page="auto-law-unavailable"] {
    background-image:
      linear-gradient(180deg, rgba(7, 5, 4, 0) 0%, rgba(7, 5, 4, 0.08) 34%, rgba(7, 5, 4, 0.92) 61%, rgba(7, 5, 4, 0.98) 100%),
      url("/block/404/keis-404-section-unavailable.webp");
    background-size: cover, 100% auto;
    background-position: center, center top;
  }

  .auto-unavailable {
    width: min(100% - 32px, 640px);
    align-items: flex-start;
    min-height: 100svh;
    padding: calc(56.25vw + clamp(18px, 4vw, 42px)) 0 clamp(28px, 8vh, 56px);
  }

  .auto-unavailable__content {
    width: 100%;
  }

  .auto-unavailable__content > p {
    font-size: 17px;
    max-width: 28em;
  }
}

@media (max-width: 480px) {
  body[data-page="auto-law-unavailable"] {
    background-position: center, center top;
  }

  .auto-unavailable {
    width: calc(100% - 24px);
    padding-top: clamp(300px, calc(56.25vw + 78px), 380px);
  }

  .auto-unavailable__button {
    width: 100%;
  }
}

/* Restore card hover motion in the mid-page problem blocks without re-enabling running glare. */
@media (hover: hover) and (pointer: fine) {
  body #kgx-b4 .kgx-b4__item,
  body .investment-challenges .challenge-card,
  body[data-page^="consumer-protection"] .investment-challenges .challenge-card {
    pointer-events: auto !important;
    transform: translate3d(0, 0, 0) !important;
    transition:
      transform 220ms cubic-bezier(.2,.7,.2,1) !important,
      border-color 220ms ease !important,
      box-shadow 220ms ease !important,
      background-color 220ms ease !important,
      filter 220ms ease !important;
    will-change: transform, border-color, box-shadow, filter !important;
  }

  body #kgx-b4 .kgx-b4__item:hover,
  body .investment-challenges .challenge-card:hover,
  body[data-page^="consumer-protection"] .investment-challenges .challenge-card:hover {
    animation: kg-glass-shimmer 720ms cubic-bezier(.22,.61,.36,1) 1 !important;
    transform: translate3d(0, -4px, 0) !important;
    filter: brightness(1.045) saturate(1.035) !important;
    border-color: rgba(236, 132, 58, .42) !important;
    box-shadow:
      0 18px 44px rgba(0, 0, 0, .42),
      inset 0 1px 0 rgba(255, 255, 255, .12),
      inset 0 0 0 1px rgba(236, 132, 58, .10) !important;
  }

  body #kgx-b4 .kgx-b4__item:hover .kgx-b4__item-title::after {
    transform: scaleX(1) !important;
  }
}
